import SwiftUI
import SignalTrackerCore
struct SettingsView:View {
    @EnvironmentObject var field: FieldModel
    @State private var deleteLocal = false
    @State private var deleteCloud = false
    var body:some View {Form {Section("Field controls") {Picker("Battery mode",selection:$field.state.settings.batteryMode) {Text("High accuracy").tag(BatteryMode.highAccuracy);Text("Balanced").tag(BatteryMode.balanced);Text("Battery saver").tag(BatteryMode.batterySaver)};Toggle("Smooth signal graphs",isOn:$field.state.settings.smoothing);Toggle("Use offline coordinate map",isOn:$field.state.settings.coordinateOnlyMap);Text("Recording is foreground-only. Sessions save and stop when you leave the app.").font(.caption)};Section("Optional cloud sync") {Toggle("Enable synchronization",isOn:$field.state.settings.syncEnabled);TextField("HTTPS API URL",text:$field.state.settings.apiURL).textInputAutocapitalization(.never);TextField("HTTPS OIDC issuer",text:$field.state.settings.issuer).textInputAutocapitalization(.never);TextField("Public client ID",text:$field.state.settings.clientID).textInputAutocapitalization(.never);TextField("API audience",text:$field.state.settings.audience).textInputAutocapitalization(.never);Button("Sign in") {Task {do{try await field.auth.signIn(settings:field.state.settings)}catch{field.message=error.localizedDescription}}};Button("Sign out") {field.signOut()};Button("Sync saved sessions now") {Task {await field.syncNow()}};Button("Download cloud sessions") {Task {await field.downloadCloudHistory()}};Text(field.syncStatus).font(.caption);Text("No automatic background uploads. Sign-in tokens are kept in Keychain. Network path availability is not a cellular-service guarantee.").font(.caption)};Section("Privacy") {Text("Location and RF records stay on this device until you explicitly upload or export. The app has no analytics or covert tracking.");Button("Delete all local history",role:.destructive) {deleteLocal=true};Button("Delete my cloud history",role:.destructive) {deleteCloud=true};Text("Deleting local history also deletes beacons, bookmarks and pending uploads. Cloud copies require a separate authenticated delete.").font(.caption)}}.navigationTitle("Settings & Privacy").confirmationDialog("Delete all local history?",isPresented:$deleteLocal,titleVisibility:.visible) {Button("Delete local history",role:.destructive) {field.deleteLocalHistory()}}.confirmationDialog("Delete all of your cloud recordings?",isPresented:$deleteCloud,titleVisibility:.visible) {Button("Delete cloud history",role:.destructive) {Task {await field.deleteCloudHistory()}}}}
}
